input.command:
mkdir -p src && cat > package.json <<'EOF'
{
  "name": "cocoon-ai",
  "version": "0.0.1",
  "description": "Components and utilities for the Cocoon creative tech studio site (React 19 + react-three-fiber).",
  "type": "module",
  "files": [
    "dist"
  ],
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "scripts": {
    "dev": "vite build --watch",
    "build": "vite build",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "peerDependencies": {
    "@react-three/fiber": "^9.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "three": ">=0.170.0"
  },
  "peerDependenciesMeta": {
    "@react-three/fiber": {
      "optional": true
    },
    "three": {
      "optional": true
    }
  }
}
EOF
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import dts from 'vite-plugin-dts'
import { resolve } from 'node:path'
import { peerDependencies } from './package.json'

// Anything the consuming app already provides must not be bundled into the lib.
const external = [
  ...Object.keys(peerDependencies),
  'react/jsx-runtime',
  'react/jsx-dev-runtime',
  /^three\//,
]

export default defineConfig({
  plugins: [
    react(),
    dts({
      tsconfigPath: './tsconfig.build.json',
      rollupTypes: true,
    }),
  ],
  build: {
    lib: {
      entry: resolve(__dirname, 'src/index.ts'),
      formats: ['es'],
      fileName: 'index',
    },
    rollupOptions: {
      external,
    },
    sourcemap: true,
    // Leave minification to the consumer's bundler so stack traces stay readable.
    minify: false,
  },
})
EOF
cat > tsconfig.json <<'EOF'
{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2022", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "moduleResolution": "bundler",
    "jsx": "react-jsx",
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "isolatedModules": true,
    "resolveJsonModule": true,
    "skipLibCheck": true,
    "noEmit": true,
    "types": ["vite/client", "@react-three/fiber"],
    "baseUrl": ".",
    "paths": {
      "@/*": ["src/*"]
    }
  },
  "include": ["src", "vite.config.ts"]
}
EOF
cat > tsconfig.build.json <<'EOF'
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "noEmit": false,
    "declaration": true,
    "emitDeclarationOnly": true,
    "outDir": "dist"
  },
  "include": ["src"]
}
EOF
cat > src/index.ts <<'EOF'
// Public entry point for the cocoon-ai library.
// Everything the website consumes gets re-exported from here.

export const VERSION = '0.0.1'
EOF
cat > .gitignore <<'EOF'
node_modules
dist
*.tsbuildinfo
.DS_Store
*.log
.vite
EOF
cat > README.md <<'EOF'
# cocoon-ai

Component and utility library for the Cocoon studio site — a dual-engine React 19 / react-three-fiber app.

Built with Vite in library mode. `react`, `react-dom`, `three` and `@react-three/fiber` are peer dependencies and are never bundled.

```bash
npm run build      # emit dist/index.js + dist/index.d.ts
npm run dev        # rebuild on change
npm run typecheck
```
EOF
npm install -D vite @vitejs/plugin-react vite-plugin-dts typescript react react-dom @types/react @types/react-dom three @types/three @react-three/fiber 2>&1 | tail -5

npm uninstall typescript vite-plugin-dts @types/node @types/react @types/react-dom @types/three 2>&1 | tail -1
rm -f tsconfig.json tsconfig.build.json vite.config.ts src/index.ts
rm -rf dist
cat > vite.config.js <<'EOF'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { peerDependencies } from './package.json' with { type: 'json' }

// Anything the consuming app already provides must not be bundled into the lib.
const external = [
  ...Object.keys(peerDependencies),
  'react/jsx-runtime',
  'react/jsx-dev-runtime',
  /^three\//,
]

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: { '@': '/src' },
  },
  build: {
    lib: {
      entry: 'src/index.js',
      formats: ['es'],
      fileName: 'index',
    },
    rollupOptions: { external },
    sourcemap: true,
    // Leave minification to the consumer's bundler so stack traces stay readable.
    minify: false,
  },
})
EOF
cat > jsconfig.json <<'EOF'
{
  "compilerOptions": {
    "module": "ESNext",
    "moduleResolution": "bundler",
    "target": "ES2022",
    "jsx": "react-jsx",
    "checkJs": false,
    "paths": {
      "@/*": ["./src/*"]
    }
  },
  "include": ["src", "vite.config.js"]
}
EOF
cat > src/index.js <<'EOF'
// Public entry point for the cocoon-ai library.
// Everything the website consumes gets re-exported from here.

export const VERSION = '0.0.1'
EOF
# strip the TS-only bits from package.json
node -e '
const fs=require("fs");const p=JSON.parse(fs.readFileSync("package.json","utf8"));
delete p.types; delete p.exports["."].types; delete p.scripts.typecheck;
fs.writeFileSync("package.json", JSON.stringify(p,null,2)+"\n")'
sed -i '' -e 's/dist\/index.js + dist\/index.d.ts/dist\/index.js/' -e '/npm run typecheck/d' README.md
echo "--- build ---"; npm run build 2>&1 | tail -6; echo "--- dist ---"; ls dist; cat dist/index.js; echo "--- pkg ---"; cat package.json

